import{_ as t,c as a,o as r,a9 as i}from"./chunks/framework.Bqk8xQPS.js";const p=JSON.parse('{"title":"Event Bridges","description":"Choose the right PURISTA event bridge and understand delivery semantics","frontmatter":{"title":"Event Bridges","description":"Choose the right PURISTA event bridge and understand delivery semantics","order":301000},"headers":[],"relativePath":"handbook/3_eco_system/eventbridges/index.md","filePath":"handbook/3_eco_system/eventbridges/index.md","lastUpdated":1775116212000}'),d={name:"handbook/3_eco_system/eventbridges/index.md"};function n(o,e,l,s,c,h){return r(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="event-bridges" tabindex="-1">Event Bridges <a class="header-anchor" href="#event-bridges" aria-label="Permalink to “Event Bridges”">​</a></h1><p>Event bridges are the transport backbone of PURISTA. They determine routing, scaling behavior, durability options, and delivery guarantees.</p><h2 id="support-matrix" tabindex="-1">Support matrix <a class="header-anchor" href="#support-matrix" aria-label="Permalink to “Support matrix”">​</a></h2><p>| bridge | scale out | durable backlog | typical delivery mode | late response handling | stream support (<code>openStream</code>) | |---|---😐---😐---|---😐 | <a href="./default_event_bridge.html">Default</a> | no | no | at-most-once (in-memory) | ignored with warning after timeout | yes | | <a href="./amqp.html">AMQP</a> | yes | yes | at-least-once for durable queues with manual ack | ignored with warning after timeout | no (currently) | | <a href="./mqtt.html">MQTT</a> | yes | broker-dependent | QoS dependent (0/1/2) | ignored with warning after timeout | no (currently) | | <a href="./nats.html">NATS</a> | yes | yes with JetStream, no with core NATS | at-most-once on core NATS, at-least-once with JetStream durable consumers | not applicable | no (currently) | | <a href="./dapr.html">Dapr</a> | yes | component-dependent | component-dependent (often at-least-once) | not applicable | no (currently) |</p><h3 id="command-reliability-model" tabindex="-1">Command reliability model <a class="header-anchor" href="#command-reliability-model" aria-label="Permalink to “Command reliability model”">​</a></h3><table tabindex="0"><thead><tr><th>bridge</th><th>command transport</th><th style="text-align:right;">pending invocation cancellation on shutdown</th><th>response confirmation</th></tr></thead><tbody><tr><td><a href="./default_event_bridge.html">Default</a></td><td>in-memory</td><td style="text-align:right;">yes</td><td>none</td></tr><tr><td><a href="./amqp.html">AMQP</a></td><td>reply queue</td><td style="text-align:right;">yes</td><td>broker confirm</td></tr><tr><td><a href="./mqtt.html">MQTT</a></td><td>topic correlation</td><td style="text-align:right;">yes</td><td>protocol-level (QoS dependent)</td></tr><tr><td><a href="./nats.html">NATS</a></td><td>request/reply</td><td style="text-align:right;">no (request timeout owned by NATS request call)</td><td>protocol-level</td></tr><tr><td><a href="./dapr.html">Dapr</a></td><td>HTTP request</td><td style="text-align:right;">no (request lifecycle owned by sidecar/client timeout)</td><td>protocol-level</td></tr></tbody></table><h3 id="subscription-consumer-failure-handling" tabindex="-1">Subscription consumer failure handling <a class="header-anchor" href="#subscription-consumer-failure-handling" aria-label="Permalink to “Subscription consumer failure handling”">​</a></h3><table tabindex="0"><thead><tr><th>bridge</th><th style="text-align:right;">bounded retry</th><th style="text-align:right;">delayed retry</th><th style="text-align:right;">dead-letter target</th><th style="text-align:right;">strict startup validation</th></tr></thead><tbody><tr><td><a href="./default_event_bridge.html">Default</a></td><td style="text-align:right;">no</td><td style="text-align:right;">no</td><td style="text-align:right;">no</td><td style="text-align:right;">yes</td></tr><tr><td><a href="./amqp.html">AMQP</a></td><td style="text-align:right;">yes</td><td style="text-align:right;">yes, broker-managed delayed retry queue when <code>retryDelayMs &gt; 0</code> on durable subscriptions</td><td style="text-align:right;">yes</td><td style="text-align:right;">yes</td></tr><tr><td><a href="./mqtt.html">MQTT</a></td><td style="text-align:right;">no</td><td style="text-align:right;">no</td><td style="text-align:right;">no</td><td style="text-align:right;">yes</td></tr><tr><td><a href="./nats.html">NATS</a></td><td style="text-align:right;">yes with JetStream</td><td style="text-align:right;">yes with JetStream</td><td style="text-align:right;">yes with JetStream</td><td style="text-align:right;">yes</td></tr><tr><td><a href="./dapr.html">Dapr</a></td><td style="text-align:right;">component-dependent</td><td style="text-align:right;">component-dependent</td><td style="text-align:right;">component-dependent</td><td style="text-align:right;">yes</td></tr></tbody></table><h3 id="queue-bridge-support" tabindex="-1">Queue bridge support <a class="header-anchor" href="#queue-bridge-support" aria-label="Permalink to “Queue bridge support”">​</a></h3><table tabindex="0"><thead><tr><th>queue bridge package</th><th>preferred workloads</th><th>compatible event bridges</th></tr></thead><tbody><tr><td><code>@purista/core</code> default queue bridge</td><td>local dev, unit tests, single instance deployments</td><td>Any (in-memory inside the service)</td></tr><tr><td><code>@purista/redis-queue-bridge</code></td><td>production pull-based CQRS, delayed jobs, AI worker pools</td><td>Default, AMQP, MQTT, NATS, Dapr (redis acts as the queue backend while the event bridge handles command/subscription traffic)</td></tr><tr><td><code>@purista/nats-queue-bridge</code></td><td>production pull-based workloads on NATS-first platforms</td><td>Default, AMQP, MQTT, NATS, Dapr (JetStream acts as the queue backend while the event bridge handles command/subscription traffic)</td></tr></tbody></table><p>Future queue bridge packages will live next to the event bridge adapters once those providers expose reliable pull + lease semantics. When evaluating infrastructure, pick an event bridge + queue bridge pair that matches your durability and scaling needs.</p><p>See the dedicated <a href="./../queue_bridges/">Queue Bridges</a> page for wiring guidance and capability details.</p><h2 id="delivery-semantics-in-practice" tabindex="-1">Delivery semantics in practice <a class="header-anchor" href="#delivery-semantics-in-practice" aria-label="Permalink to “Delivery semantics in practice”">​</a></h2><p>PURISTA itself provides typed message contracts and processing flow. Delivery guarantees come from the selected bridge + broker/component configuration.</p><ul><li><code>at-most-once</code>: low latency, but a message can be lost on failures.</li><li><code>at-least-once</code>: safer delivery, but duplicates are possible.</li><li><code>exactly-once</code>: generally not guaranteed end-to-end in distributed systems; design handlers to be idempotent.</li></ul><p>Late command responses are normalized across invoke-capable bridges in this slice. Once the caller-side timeout fires, PURISTA keeps a short-lived tombstone for the correlation id and ignores any later response with a warning instead of raising a bridge error.</p><p>Subscription retry and dead-letter handling are capability-driven bridge concerns. Service definitions can declare consumer failure handling in <code>strict</code> or <code>best-effort</code> mode. In <code>strict</code> mode, PURISTA fails startup if the selected adapter cannot honor the requested semantics. Exhausted subscription messages are dead-lettered; PURISTA no longer exposes unimplemented <code>drop</code> or <code>stop-consumer</code> outcomes in the public contract.</p><p>Command registrations now follow the same strict startup validation approach for delivery semantics. If a command requests durable/manual-ack handling that the active bridge cannot provide, startup fails early instead of silently degrading.</p><h2 id="reliability-checklist" tabindex="-1">Reliability checklist <a class="header-anchor" href="#reliability-checklist" aria-label="Permalink to “Reliability checklist”">​</a></h2><ul><li>configure broker durability/retry features explicitly</li><li>keep bridge settings identical across instances</li><li>implement idempotency in command/subscription side effects</li><li>define timeout/retry policies intentionally (do not rely on defaults only)</li><li>keep subscription retry budgets bounded and route poison messages to a dead-letter target</li><li>verify shutdown, readiness, and reconnect semantics in integration tests</li><li>test reconnect and broker outage scenarios in integration tests</li></ul><h2 id="when-to-use-which-bridge" tabindex="-1">When to use which bridge <a class="header-anchor" href="#when-to-use-which-bridge" aria-label="Permalink to “When to use which bridge”">​</a></h2><ul><li><code>DefaultEventBridge</code>: local development, single-instance deployments, stream development.</li><li><code>AMQP</code>: production systems with durable queues/retries and strong operational control.</li><li><code>MQTT</code>: IoT/edge and broker setups where topic/QoS tuning is central.</li><li><code>NATS</code>: low-latency eventing where simple operations are preferred.</li><li><code>NATS</code> with JetStream: good fit when you want bounded subscription retries and dead-letter subjects without introducing a separate queue backend.</li><li><code>Dapr</code>: polyglot/service-mesh environments leveraging Dapr components.</li></ul>',22)])])}const g=t(d,[["render",n]]);export{p as __pageData,g as default};
